import{_ as t,o,c as r,ah as a}from"./chunks/framework.C-FRNfAJ.js";const p=JSON.parse('{"title":"Coach-Tutor","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/equipe/coach-tuteur.md","filePath":"src/en/guide/equipe/coach-tuteur.md"}'),n={name:"en/guide/equipe/coach-tuteur.md"};function s(i,e,h,u,c,d){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="coach-tutor" tabindex="-1">Coach-Tutor <a class="header-anchor" href="#coach-tutor" aria-label="Permalink to &quot;Coach-Tutor&quot;">​</a></h1><p>The Coach-Tutor individually accompanies a cohort&#39;s learners. Their workspace is in <strong>Sève</strong>, with messaging. In <strong>Kura</strong>, they find their cohorts and their remuneration.</p><h2 id="getting-the-role" tabindex="-1">Getting the role <a class="header-anchor" href="#getting-the-role" aria-label="Permalink to &quot;Getting the role&quot;">​</a></h2><p>A <strong>Canopé</strong> account (a former certified learner) can ask for the role in <strong>Settings → Roles</strong>. The Pedagogical Coordinator examines the request and tells you of their decision. If they refuse it, they give you the reason and your other roles do not change. The Coordinator can also assign you the role directly.</p><h2 id="your-cohorts" tabindex="-1">Your cohorts <a class="header-anchor" href="#your-cohorts" aria-label="Permalink to &quot;Your cohorts&quot;">​</a></h2><p>Like the Lead Trainer, in <strong>Training → Cohorts</strong> you only see the cohorts you are <strong>assigned</strong> to. The page shows learners, their formats and statuses, with the &quot;No image rights&quot; marker for those who refused, and lets you download the cohort&#39;s <strong>provisional calendar</strong>.</p><p>Your name and e-mail address appear in the <strong>welcome booklet</strong> of the cohort&#39;s learners, so they know whom to contact.</p><h2 id="supervising-an-internship" tabindex="-1">Supervising an internship <a class="header-anchor" href="#supervising-an-internship" aria-label="Permalink to &quot;Supervising an internship&quot;">​</a></h2><p>If the training includes an internship, the Coordinator can designate you <strong>internship Coach-Tutor</strong> among the cohort&#39;s. Your name then appears on the <strong>internship agreement</strong>, which the learner and the company sign. You receive its PDF once the agreement is counter-signed by edPage group.</p><h2 id="your-remuneration" tabindex="-1">Your remuneration <a class="header-anchor" href="#your-remuneration" aria-label="Permalink to &quot;Your remuneration&quot;">​</a></h2><p><strong>Finance → My remuneration</strong> shows your lines cohort by cohort, your payouts, and three totals: awaiting validation, validated to pay, paid.</p><p>Your remuneration is a <strong>lump sum per supervised learner</strong>, calculated by Kura at the end of the cohort on the headcount present at its start, even if a learner dropped out afterwards. Lump sums add up from one cohort to the next. With several Coach-Tutors on the same cohort, it is split equally. The Coordinator validates it, then records the payment made outside Kura.</p>',12)])])}const g=t(n,[["render",s]]);export{p as __pageData,g as default};
